{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#"
      }
    },
    {
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "#"
      }
    },
    {
      "description": "A string value.",
      "type": "string"
    },
    {
      "description": "An integer value.",
      "type": "integer",
      "format": "int64"
    },
    {
      "description": "A floating-point number.",
      "type": "number",
      "format": "double"
    },
    {
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  },
  "required": [
    "anyOf"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "type": [
        "string",
        "null"
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "type": [
        "string",
        "null"
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "type": [
        "string",
        "null"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentExpression",
  "description": "Expression variant of [`RichContent`] for dynamic content.",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content expressions.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentPartExpression"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentExpression",
  "description": "Expression variant of [`RichContent`] for dynamic content.",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content expressions.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentPartExpression"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.AssistantToolCallExpression",
  "description": "Expression variant of [`AssistantToolCall`] for dynamic content.",
  "oneOf": [
    {
      "description": "A function call expression.",
      "type": "object",
      "properties": {
        "id": {
          "description": "The tool call ID expression.",
          "$ref": "functions.expression.WithExpression.string"
        },
        "function": {
          "description": "The function expression.",
          "$ref": "functions.expression.WithExpression.agent.completions.message.AssistantToolCallFunctionExpression"
        },
        "type": {
          "type": "string",
          "const": "function"
        }
      },
      "required": [
        "type",
        "id",
        "function"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.AssistantToolCallExpression",
  "description": "Expression variant of [`AssistantToolCall`] for dynamic content.",
  "oneOf": [
    {
      "description": "A function call expression.",
      "type": "object",
      "properties": {
        "id": {
          "description": "The tool call ID expression.",
          "$ref": "functions.expression.WithExpression.string"
        },
        "function": {
          "description": "The function expression.",
          "$ref": "functions.expression.WithExpression.agent.completions.message.AssistantToolCallFunctionExpression"
        },
        "type": {
          "type": "string",
          "const": "function"
        }
      },
      "required": [
        "type",
        "id",
        "function"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "oneOf": [
    {
      "description": "Returns the params input as-is.",
      "type": "string",
      "const": "input"
    },
    {
      "description": "Returns the params output as-is.",
      "type": "string",
      "const": "output"
    },
    {
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "const": "task_output_l1_normalized"
    },
    {
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "const": "task_output_weighted_sum"
    },
    {
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "const": "input_items_output_length"
    },
    {
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "const": "input_items_optional_context_split"
    },
    {
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "const": "input_items_optional_context_merge"
    }
  ]
}
